<template>
  <div class="admin-layout">
    <AdminNavigation />
    <main class="admin-container">
      <header class="page-header"><div><p class="eyebrow">КОНТЕНТ</p><h1>Проекты</h1><p class="subtitle">Управляйте собственными проектами и коммерческим опытом.</p></div><button class="primary-button" @click="openCreate">Добавить проект</button></header>
      <p v-if="notice" class="notice" role="status">{{ notice }}</p>
      <div v-if="loading" class="state">Загружаем проекты…</div>
      <div v-else-if="error" class="state state--error"><span>{{ error }}</span><button class="secondary-button" @click="fetchAdminProjects">Попробовать снова</button></div>
      <div v-else class="project-list">
        <article v-for="project in projectItems" :key="project.id" class="project-row">
          <img class="preview" :src="project.image" :alt="`Превью: ${project.title}`" />
          <div class="project-content"><div class="title-line"><h2>{{ project.title }}</h2><span class="ownership" :class="`ownership--${project.ownershipType.toLowerCase()}`">{{ ownershipLabel(project.ownershipType) }}</span></div><p>{{ project.projectSummary || project.shortDescription }}</p><div class="meta"><span>{{ project.category }}</span><span>{{ project.featured ? 'Избранный' : 'Обычный' }}</span><span>Порядок {{ project.order }}</span><a v-if="project.liveUrl" :href="project.liveUrl" target="_blank" rel="noopener noreferrer">Production ↗</a></div></div>
          <div class="actions"><button class="secondary-button" @click="openEdit(project)">Редактировать</button><button class="danger-button" @click="openDelete(project)">Удалить</button></div>
        </article>
        <p v-if="!projectItems.length" class="state">Пока нет проектов. Добавьте первый кейс.</p>
      </div>
    </main>

    <AdminDialog v-model="editorOpen" :title="editingId ? 'Редактировать проект' : 'Новый проект'" description="Публичные сведения должны точно отражать вашу роль и вклад." size="xl" @request-close="requestClose">
      <div class="editor-grid">
        <form id="project-editor" class="editor-form" novalidate @submit.prevent="saveProject">
          <section class="form-section"><h3>Основное</h3><div class="fields-two"><Field label="Название" :error="errors.title"><input v-model="form.title" required /></Field><Field label="Категория"><input v-model="form.category" required /></Field></div><Field label="Краткое описание"><textarea v-model="form.description" rows="2" required /></Field><div class="fields-two"><Field label="Превью · путь или https URL" :error="errors.image"><input v-model="form.image" placeholder="/images/projects/example.webp" required /></Field><Field label="Порядок"><input v-model.number="form.order" type="number" min="0" /></Field></div></section>

          <section class="form-section"><h3>Тип проекта</h3><div class="ownership-options" role="radiogroup" aria-label="Тип проекта"><button v-for="option in ownershipOptions" :key="option.value" type="button" class="ownership-option" :class="{ 'is-selected': form.ownershipType === option.value }" role="radio" :aria-checked="form.ownershipType === option.value" :tabindex="form.ownershipType === option.value ? 0 : -1" @click="setOwnershipType(option.value)" @keydown="handleOwnershipKeydown($event, option.value)"><strong>{{ option.label }}</strong><span>{{ option.description }}</span></button></div></section>

          <section class="form-section"><h3>Case study</h3><Field label="О продукте" :error="errors.projectSummary"><textarea v-model="form.projectSummary" rows="3" :required="form.ownershipType !== 'UNVERIFIED'" /></Field><template v-if="form.ownershipType !== 'UNVERIFIED'"><div class="fields-two"><Field label="Моя роль" :error="errors.role"><input v-model="form.role" /></Field><Field :label="form.ownershipType === 'CLIENT' ? 'Заказчик / компания' : 'Компания / команда'"><input v-model="form.company" /></Field></div><RepeatableField v-model="form.responsibilities" :label="form.ownershipType === 'CLIENT' ? 'Что я реализовал' : form.ownershipType === 'OWN' ? 'Моя работа' : 'Мой вклад'" placeholder="Конкретная задача, компонент или подсистема" :error="errors.responsibilities" /><RepeatableField v-model="form.technicalHighlights" label="Технические решения" placeholder="Компонент, подсистема или решение" /><RepeatableField v-model="form.technologies" label="Стек" placeholder="Например, Nuxt 3" :error="errors.technologies" /></template><p v-else class="muted-note">Роль, вклад и технологии сохраняются скрытыми до подтверждения проекта.</p></section>

          <section class="form-section"><h3>Ссылки и публикация</h3><div class="fields-two"><Field label="Production URL" :error="errors.liveUrl"><input v-model="form.liveUrl" type="url" placeholder="https://…" /></Field><Field label="Репозиторий"><input v-model="form.githubUrl" type="url" placeholder="https://github.com/…" /></Field></div><label class="check-row"><input v-model="form.featured" type="checkbox" :disabled="form.ownershipType === 'UNVERIFIED'" /> Показывать в избранном</label></section>
          <p v-if="saveError" class="form-error" role="alert">{{ saveError }}</p>
        </form>

        <aside class="preview-panel"><p class="eyebrow">ПРЕДПРОСМОТР</p><span class="ownership" :class="`ownership--${form.ownershipType.toLowerCase()}`">{{ ownershipLabel(form.ownershipType) }}</span><div class="preview-card"><img v-if="safePreview" :src="safePreview" alt="" /><div class="preview-card__body"><h3>{{ form.title || 'Название проекта' }}</h3><p>{{ form.projectSummary || 'Краткое описание продукта появится здесь.' }}</p><template v-if="form.ownershipType !== 'UNVERIFIED'"><p v-if="form.role" class="role">{{ form.role }}<span v-if="form.company"> · {{ form.company }}</span></p><ul><li v-for="item in form.responsibilities.slice(0, 2)" :key="item">{{ item }}</li></ul><div class="tags"><span v-for="tag in form.technologies.slice(0, 4)" :key="tag">{{ tag }}</span></div></template></div></div><p class="preview-hint">Предпросмотр показывает только первые пункты вклада и стека.</p></aside>
      </div>
      <template #footer><div class="dialog-actions"><span v-if="saveError" class="footer-error">Исправьте ошибки формы перед сохранением.</span><button class="secondary-button" type="button" @click="requestClose">Отмена</button><button class="primary-button" type="submit" form="project-editor" :disabled="submitting">{{ submitting ? 'Сохраняем…' : editingId ? 'Сохранить изменения' : 'Создать проект' }}</button></div></template>
    </AdminDialog>

    <AdminDialog v-model="discardChangesOpen" title="Несохранённые изменения" description="Изменения в редакторе не сохранены." size="sm" @request-close="discardChangesOpen = false">
      <p class="delete-copy">Закрыть редактор и потерять введённые данные?</p>
      <template #footer><div class="dialog-actions"><button class="secondary-button" type="button" @click="discardChangesOpen = false">Остаться</button><button class="danger-button" type="button" @click="discardChanges">Не сохранять</button></div></template>
    </AdminDialog>

    <AdminDialog v-model="deleteOpen" title="Удалить проект?" :description="`«${deletingProject?.title ?? ''}» будет удалён из портфолио.`" size="sm" @request-close="deleteOpen = false">
      <p class="delete-copy">Действие нельзя отменить. Проект исчезнет из публичного списка только после подтверждения удаления сервером.</p><p v-if="deleteError" class="form-error" role="alert">{{ deleteError }}</p>
      <template #footer><div class="dialog-actions"><button class="secondary-button" :disabled="submitting" @click="deleteOpen = false">Отмена</button><button class="danger-button" :disabled="submitting" @click="confirmDelete">{{ submitting ? 'Удаляем…' : 'Удалить проект' }}</button></div></template>
    </AdminDialog>
  </div>
</template>

<script setup lang="ts">
import type { AdminProject } from "~/composables/useProjects";
import type { ProjectFormInput, ProjectOwnershipType } from "~/types/project-case-study";
import { isUsableProjectPreview } from "~/utils/project-links";
import Field from "~/components/admin/Field.vue";
import RepeatableField from "~/components/admin/RepeatableField.vue";
const { projects, loading, error, fetchAdminProjects, createProject, updateProject, deleteProject } = useProjects();
const projectItems = computed(() => projects.value as unknown as AdminProject[]);
const editorOpen = ref(false), discardChangesOpen = ref(false), deleteOpen = ref(false), submitting = ref(false), editingId = ref<string | null>(null), deletingProject = ref<AdminProject | null>(null), notice = ref(""), saveError = ref(""), deleteError = ref("");
const ownershipOptions: { value: ProjectOwnershipType; label: string; description: string }[] = [
  { value: "OWN", label: "Мой проект", description: "Вы основной автор и отвечаете за продукт." },
  { value: "CLIENT", label: "Клиентский проект", description: "Самостоятельная или основная реализация для заказчика." },
  { value: "PARTICIPATION", label: "Участие", description: "Вы реализовали часть продукта другой команды." },
  { value: "UNVERIFIED", label: "Не подтверждён", description: "Публичные claims о роли и стеке скрыты." },
];
function setOwnershipType(type: ProjectOwnershipType) { form.ownershipType = type; clearErrors(); saveError.value = ""; }
const emptyForm = (): ProjectFormInput => ({ title: "", shortDescription: "", description: "", image: "", category: "", ownershipType: "OWN", projectSummary: "", role: "", company: "", responsibilities: [""], technicalHighlights: [""], technologies: [""], liveUrl: "", githubUrl: "", featured: false, order: 0 });
const form = reactive<ProjectFormInput>(emptyForm());
const original = ref("");
const errors = reactive<Record<string, string>>({});
const safePreview = computed(() => isUsableProjectPreview(form.image) ? form.image : "");
onMounted(fetchAdminProjects);
function ownershipLabel(type: ProjectOwnershipType) { return ({ OWN: "Мой проект", CLIENT: "Клиентский проект", PARTICIPATION: "Участие", UNVERIFIED: "Не подтверждён" })[type]; }
function handleOwnershipKeydown(event: KeyboardEvent, currentType: ProjectOwnershipType) {
  const currentIndex = ownershipOptions.findIndex((option) => option.value === currentType);
  let nextIndex = currentIndex;
  if (event.key === "ArrowRight" || event.key === "ArrowDown") nextIndex = (currentIndex + 1) % ownershipOptions.length;
  else if (event.key === "ArrowLeft" || event.key === "ArrowUp") nextIndex = (currentIndex - 1 + ownershipOptions.length) % ownershipOptions.length;
  else if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = ownershipOptions.length - 1;
  else return;
  event.preventDefault();
  setOwnershipType(ownershipOptions[nextIndex].value);
  nextTick(() => document.querySelector<HTMLButtonElement>(`.ownership-option[aria-checked="true"]`)?.focus());
}
function openCreate() { editingId.value = null; Object.assign(form, emptyForm()); clearErrors(); original.value = JSON.stringify(form); editorOpen.value = true; saveError.value = ""; }
function openEdit(project: AdminProject) { editingId.value = project.id; Object.assign(form, { ...emptyForm(), ...project, shortDescription: project.shortDescription || project.projectSummary || "", projectSummary: project.projectSummary || project.shortDescription || "", role: project.role || "", company: project.company || "", responsibilities: project.responsibilities?.length ? [...project.responsibilities] : [""], technicalHighlights: project.technicalHighlights?.length ? [...project.technicalHighlights] : [""], technologies: [...(project.technologies || []), ...(project.technologies?.length ? [] : [""])], liveUrl: project.liveUrl || "", githubUrl: project.githubUrl || "" }); clearErrors(); original.value = JSON.stringify(form); editorOpen.value = true; saveError.value = ""; }
function clearErrors() { for (const key of Object.keys(errors)) errors[key] = ""; }
function requestClose() { if (submitting.value) return; if (JSON.stringify(form) !== original.value) { discardChangesOpen.value = true; return; } editorOpen.value = false; }
async function discardChanges() { discardChangesOpen.value = false; await nextTick(); editorOpen.value = false; }
function validate() { clearErrors(); if (!form.title.trim()) errors.title = "Укажите название"; if (!form.category.trim()) errors.category = "Укажите категорию"; if (!form.image.trim() || !isUsableProjectPreview(form.image)) errors.image = "Укажите безопасный путь или http(s) URL превью"; if (form.ownershipType !== "UNVERIFIED") { if (!form.projectSummary.trim()) errors.projectSummary = "Добавьте описание продукта"; if (!form.role.trim()) errors.role = "Укажите роль"; if (!(form.responsibilities as string[]).some((item: string) => item.trim())) errors.responsibilities = "Добавьте хотя бы один пункт вклада"; if (form.ownershipType === "OWN" && !(form.technologies as string[]).some((item: string) => item.trim())) errors.technologies = "Добавьте хотя бы одну технологию"; } for (const [key, value] of [["liveUrl", form.liveUrl], ["githubUrl", form.githubUrl]] as const) if (value && !/^https?:\/\//i.test(value)) errors[key] = "Разрешены только http и https"; return !Object.values(errors).some(Boolean); }
async function saveProject() { saveError.value = ""; if (!validate()) { saveError.value = "Проверьте отмеченные поля."; return; } submitting.value = true; const payload: ProjectFormInput = { ...form, title: form.title.trim(), description: form.projectSummary.trim() || form.description.trim(), shortDescription: form.projectSummary.trim() || form.shortDescription.trim(), projectSummary: form.projectSummary.trim(), responsibilities: (form.responsibilities as string[]).map((item: string) => item.trim()).filter(Boolean), technicalHighlights: (form.technicalHighlights as string[]).map((item: string) => item.trim()).filter(Boolean), technologies: (form.technologies as string[]).map((item: string) => item.trim()).filter(Boolean), role: form.role.trim(), company: form.company.trim() }; try { const result = editingId.value ? await updateProject(editingId.value, payload) : await createProject(payload); if (!result) { saveError.value = error.value || "Не удалось сохранить проект. Проверьте подключение и права доступа."; return; } editorOpen.value = false; notice.value = editingId.value ? "Изменения сохранены." : "Проект создан."; setTimeout(() => notice.value = "", 3500); } catch (cause) { saveError.value = cause instanceof Error ? cause.message : "Не удалось сохранить проект."; } finally { submitting.value = false; } }
function openDelete(project: AdminProject) { deletingProject.value = project; deleteError.value = ""; deleteOpen.value = true; }
async function confirmDelete() { if (!deletingProject.value) return; submitting.value = true; deleteError.value = ""; try { const success = await deleteProject(deletingProject.value.id); if (!success) { deleteError.value = error.value || "Не удалось удалить проект."; return; } deleteOpen.value = false; notice.value = "Проект удалён."; setTimeout(() => notice.value = "", 3500); } catch (cause) { deleteError.value = cause instanceof Error ? cause.message : "Не удалось удалить проект."; } finally { submitting.value = false; } }
</script>

<style scoped>
