r:var(--color-primary)}.actions{display:flex;gap:8px;flex:none}.state{display:flex;align-items:center;justify-content:center;gap:12px;min-height:180px;color:var(--color-text-secondary)}.state--error{color:#b4232f}.notice{margin:0 0 16px;padding:11px 14px;border-radius:10px;background:rgba(37,140,93,.1);color:#1e754c}.editor-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,.8fr);gap:28px;align-items:start}.editor-form{display:grid;gap:22px}.form-section{display:grid;gap:14px;padding-bottom:20px;border-bottom:1px solid var(--border-color)}.form-section h3{margin:0;font-size:1rem}.fields-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.form-field{display:grid;gap:6px;min-width:0}.form-field>span{font-size:.82rem;font-weight:650}.form-field input,.form-field textarea,.repeat-item input{width:100%;box-sizing:border-box;padding:10px 11px;border:1px solid var(--border-color);border-radius:9px;background:var(--background-color);color:var(--color-text);font:inherit;font-size:.88rem}.form-field textarea{resize:vertical}.field-error{color:#c5303c;font-size:.76rem}.ownership-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.ownership-option{display:grid;align-content:start;gap:6px;padding:12px;border:1px solid var(--border-color);border-radius:11px;background:var(--background-color);color:var(--color-text);text-align:left;cursor:pointer}.ownership-option strong{font-size:.82rem}.ownership-option span{color:var(--color-text-secondary);font-size:.72rem;line-height:1.4}.ownership-option.is-selected{border-color:var(--color-primary);box-shadow:0 0 0 2px color-mix(in srgb,var(--color-primary) 18%,transparent)}.repeatable{display:grid;gap:8px}.repeat-item{display:flex;gap:7px}.icon-button{width:40px;flex:none;border:1px solid var(--border-color);border-radius:9px;background:transparent;color:var(--color-text-secondary);font-size:1.1rem;cursor:pointer}.text-button{justify-self:start;border:0;background:transparent;c