@media(max-width:1050px){.admin-container{margin-left:250px}.editor-grid{grid-template-columns:1fr}.preview-panel{position:static;grid-row:1}.preview-card{display:grid;grid-template-columns:160px 1fr}.preview-card>img{height:100%;min-height:130px}}
